import copy


def _parse_path(path):
    """Parse a JSON-Patch-style path, allowing only a single top-level key."""
    if not isinstance(path, str):
        raise ValueError("Path must be a string")
    if not path.startswith("/"):
        raise ValueError("Path must start with '/'")

    rest = path[1:]
    chars = []
    i = 0
    while i < len(rest):
        c = rest[i]
        if c == "/":
            raise ValueError("Nested paths are not allowed")
        elif c == "~":
            if i + 1 >= len(rest):
                raise ValueError("Invalid escape: trailing '~'")
            nxt = rest[i + 1]
            if nxt == "0":
                chars.append("~")
            elif nxt == "1":
                chars.append("/")
            else:
                raise ValueError(f"Invalid escape: ~{nxt!r}")
            i += 2
        else:
            chars.append(c)
            i += 1
    return "".join(chars)


def apply_patch(document, operations):
    """Apply a list of JSON-Patch-like operations to a top-level JSON object.

    Supported ops: add, replace, remove, test.
    Only top-level keys are addressed (single-segment paths).
    Returns a deep copy; never mutates document, operations, or nested values.
    """
    if not isinstance(document, dict):
        raise ValueError("document must be a JSON object (dict)")
    if not isinstance(operations, (list, tuple)):
        raise ValueError("operations must be a list")

    result = copy.deepcopy(document)

    for idx, op in enumerate(operations):
        if not isinstance(op, dict):
            raise ValueError(f"Operation {idx} is not an object")
        if "op" not in op:
            raise ValueError(f"Operation {idx} is missing 'op'")
        if "path" not in op:
            raise ValueError(f"Operation {idx} is missing 'path'")

        op_type = op["op"]
        path = op["path"]

        if op_type not in ("add", "replace", "remove", "test"):
            raise ValueError(f"Invalid operation: {op_type!r}")

        key = _parse_path(path)

        if op_type == "add":
            if "value" not in op:
                raise ValueError("Operation 'add' requires a 'value'")
            result[key] = copy.deepcopy(op["value"])

        elif op_type == "replace":
            if "value" not in op:
                raise ValueError("Operation 'replace' requires a 'value'")
            if key not in result:
                raise ValueError(f"Key {key!r} does not exist for replace")
            result[key] = copy.deepcopy(op["value"])

        elif op_type == "remove":
            if key not in result:
                raise ValueError(f"Key {key!r} does not exist for remove")
            del result[key]

        elif op_type == "test":
            if "value" not in op:
                raise ValueError("Operation 'test' requires a 'value'")
            if key not in result:
                raise ValueError(f"Key {key!r} does not exist for test")
            if result[key] != op["value"]:
                raise ValueError(f"Test failed for key {key!r}")

    return result
