def dependency_levels(graph):
    if not graph:
        return []

    # Collect all task names (keys + prerequisite-only names)
    all_tasks = set()
    for task, prereqs_list in graph.items():
        all_tasks.add(task)
        for p in prereqs_list:
            all_tasks.add(p)

    # Build deduplicated prerequisite sets (do not mutate input)
    prereqs = {task: set() for task in all_tasks}
    for task, prereqs_list in graph.items():
        for p in prereqs_list:
            prereqs[task].add(p)

    # In-degree = number of prerequisites for each task
    in_degree = {task: len(prereqs[task]) for task in all_tasks}

    # Reverse mapping: prerequisite -> list of tasks that depend on it
    dependents = {task: [] for task in all_tasks}
    for task, prereq_set in prereqs.items():
        for p in prereq_set:
            dependents[p].append(task)

    # Kahn's algorithm, level by level
    current_level = sorted(t for t in all_tasks if in_degree[t] == 0)
    levels = []
    processed = 0

    while current_level:
        levels.append(current_level)
        processed += len(current_level)
        next_level = set()
        for task in current_level:
            for dep in dependents[task]:
                in_degree[dep] -= 1
                if in_degree[dep] == 0:
                    next_level.add(dep)
        current_level = sorted(next_level)

    if processed != len(all_tasks):
        raise ValueError("Cycle detected in dependency graph")

    return levels
